export const BODY_TYPES = ['Sedan', 'SUV', 'Hatchback', 'Coupe', 'Convertible', 'Wagon', 'Pickup', 'Van', 'Sports'];
export const BODY_LABEL = { Van: 'Van / MPV', Sports: 'Sports / Supercar', Wagon: 'Wagon / Estate', Pickup: 'Pickup truck' };

const NOW = new Date().getFullYear();
export const MIN_YEAR = 1940;
export const MAX_YEAR = NOW + 1;
export const ALL_YEARS = Array.from({ length: MAX_YEAR - MIN_YEAR + 1 }, (_, i) => MAX_YEAR - i);

const tidy = (k) => k.replace(/_/g, ' ');
const ALIAS = { 'Mercedes Benz': 'Mercedes-Benz', Mg: 'MG', 'Li Auto': 'Li Auto', 'Great Wall': 'Great Wall', 'Maruti Suzuki': 'Maruti Suzuki', 'Hispano Suiza': 'Hispano-Suiza', 'Hispano_Suiza': 'Hispano-Suiza', Bmw: 'BMW', Gmc: 'GMC', Gac: 'GAC', Byd: 'BYD', Ds: 'DS', Amc: 'AMC', Uaz: 'UAZ', Gaz: 'GAZ', Citroen: 'Citroën', Skoda: 'Škoda', Nio: 'NIO', Xpeng: 'XPeng' };

const RE = /^(.+?) (\d{4}) (\d{4}|-) (Sedan|SUV|Hatchback|Coupe|Convertible|Wagon|Pickup|Van|Sports)$/;
const merged = {};
Object.entries(RAW).forEach(([rawMake, list]) => {
  if (!list.length) return;
  const base = tidy(rawMake);
  const make = ALIAS[base] ?? base;
  const seen = (merged[make] ??= new Map());
  list.forEach((s) => {
    const m = RE.exec(s);
    if (!m) return;
    const [, name, from, to, body] = m;
    const key = name.toLowerCase();
    if (!seen.has(key)) seen.set(key, { name, from: Number(from), to: to === '-' ? null : Number(to), body });
  });
});

export const CAR_DB = Object.fromEntries(
  Object.entries(merged).sort(([a], [b]) => a.localeCompare(b)).map(([k, m]) => [k, [...m.values()].sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }))])
);
export const ALL_MAKES = Object.keys(CAR_DB);

// makes that have at least one model sold in `year`
export const makesForYear = (year) => (!year ? ALL_MAKES : ALL_MAKES.filter((mk) => CAR_DB[mk].some((m) => m.from <= year && (m.to ?? 9999) >= year)));
export const modelsFor = (make, year) => (CAR_DB[make] ?? []).filter((m) => !year || (m.from <= year && (m.to ?? 9999) >= year));
export const findModel = (make, name) => (CAR_DB[make] ?? []).find((m) => m.name === name);
export const productionRange = (m) => `${m.from}–${m.to ?? 'present'}`;

// Common trims / variants (generic – the inspector can also type a custom one)
export const VARIANTS = ['Base / Standard', 'Mid-spec', 'Premium / Luxury', 'Sport', 'Limited / Special edition', 'Performance (e.g. AMG / M / RS / GT)', 'Off-road / Adventure', 'Hybrid', 'Plug-in hybrid', 'Electric', 'Diesel', 'Turbo', 'Long wheelbase', 'Convertible / Roadster', 'Other / not sure'];
export const FUEL_TYPES = ['Petrol', 'Diesel', 'Hybrid', 'Plug-in hybrid', 'Electric', 'CNG / LPG'];
